// Parse the LLM JSON; attach the source URL. Passes {error} through unchanged
// so AIFOS marks the row 'error' instead of faking success.
const llm = $input.first().json;
const content = llm.choices?.[0]?.message?.content || '{}';
let parsed = {};
try { parsed = JSON.parse(content); } catch (e) { parsed = { error: 'LLM did not return valid JSON', raw: content }; }
if (!parsed.error) parsed.source = $('Each video').item.json.url;
return [{ json: parsed }];
